Seeing it directly
Numbers aside, the clearest evidence is just looking at the images. Below, each row is one starting image; each column is the reconstruction after forward-backward diffusion at an increasing reversal timestep. At small \(t\) the reconstruction is nearly pixel-identical to the original. At larger \(t\), fine texture is the first thing to change, followed eventually by pose, composition, and — at the largest \(t\) we tested — occasionally the object itself.

library(jpeg)
library(grid)

manifest &lt;- read_csv("data/image_grid_manifest.csv", show_col_types = FALSE)
t_values &lt;- sort(unique(manifest$step_reverse[manifest$step_reverse &gt; 0]))
image_ids &lt;- unique(manifest$image_id)

grid.newpage()
n_rows &lt;- length(image_ids)
n_cols &lt;- length(t_values) + 1
pushViewport(viewport(layout = grid.layout(
  n_rows + 1, n_cols,
  heights = unit(c(1.5, rep(5, n_rows)), c("lines", rep("null", n_rows)))
)))

draw_label &lt;- function(label, col) {
  pushViewport(viewport(layout.pos.row = 1, layout.pos.col = col))
  grid.text(label, gp = gpar(fontsize = 9))
  popViewport()
}

draw_cell &lt;- function(path, row, col) {
  img &lt;- readJPEG(path)
  pushViewport(viewport(layout.pos.row = row + 1, layout.pos.col = col))
  grid.raster(img)
  popViewport()
}

draw_label("original", 1)
for (c in seq_along(t_values)) draw_label(paste0("t=", t_values[c]), c + 1)

for (r in seq_along(image_ids)) {
  row_data &lt;- manifest |&gt; filter(image_id == image_ids[r])
  start_path &lt;- row_data$path[row_data$step_reverse == 0]
  draw_cell(start_path, r, 1)
  for (c in seq_along(t_values)) {
    t_path &lt;- row_data$path[row_data$step_reverse == t_values[c]]
    if (length(t_path) == 1) {
      draw_cell(t_path, r, c + 1)
    }
  }
}







